## Goroutine Basics

```go
package main

import (
    "fmt"
    "time"
)

func fetchData(id int, results chan<- string) {
    // Simulate work
    time.Sleep(100 * time.Millisecond)
    results <- fmt.Sprintf("result from %d", id)
}

func main() {
    results := make(chan string, 5)  // Buffered channel — holds 5 without blocking

    for i := 0; i < 5; i++ {
        go fetchData(i, results)    // Each goroutine runs concurrently
    }

    for i := 0; i < 5; i++ {
        fmt.Println(<-results)      // Receive from channel
    }
}
```

## Fan-Out / Fan-In Pattern

```go
func fanOut(input <-chan int, numWorkers int) []<-chan int {
    outputs := make([]<-chan int, numWorkers)
    for i := 0; i < numWorkers; i++ {
        out := make(chan int)
        outputs[i] = out
        go func(out chan<- int) {
            for v := range input {
                out <- process(v)
            }
            close(out)
        }(out)
    }
    return outputs
}
```

## Select — Multiplexing Channels

```go
func withTimeout(ctx context.Context, work func() string) (string, error) {
    result := make(chan string, 1)
    go func() {
        result <- work()
    }()

    select {
    case r := <-result:
        return r, nil
    case <-ctx.Done():  // Timeout or cancellation
        return "", ctx.Err()
    }
}
```

## When to Use sync.Mutex

```go
// Mutex is cleaner for protecting simple shared state
type SafeCounter struct {
    mu sync.Mutex
    v  map[string]int
}

func (c *SafeCounter) Inc(key string) {
    c.mu.Lock()
    defer c.mu.Unlock()  // Deferred — always runs even if panic
    c.v[key]++
}

// sync.Map for concurrent read-heavy maps
var m sync.Map
m.Store("key", "value")
value, _ := m.Load("key")
```

## Goroutine Leak Prevention

```go
// ALWAYS use context for cancellation to prevent goroutine leaks
func processWithCancel(ctx context.Context, items []Item) <-chan Result {
    out := make(chan Result)
    go func() {
        defer close(out)  // Signal downstream that we're done
        for _, item := range items {
            select {
            case <-ctx.Done():
                return  // Context cancelled — exit goroutine
            case out <- process(item):
            }
        }
    }()
    return out
}
```

## HTTP Handler with Timeout

```go
func (h *Handler) GetUser(w http.ResponseWriter, r *http.Request) {
    // r.Context() is cancelled when client disconnects
    ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
    defer cancel()  // ALWAYS defer — frees timer resources even if fn returns early

    user, err := h.repo.GetUser(ctx, userID)
    if err != nil {
        if errors.Is(err, context.DeadlineExceeded) {
            http.Error(w, "Request timeout", http.StatusGatewayTimeout)
            return
        }
        if errors.Is(err, context.Canceled) {
            // Client disconnected — no need to respond
            return
        }
        http.Error(w, "Internal error", http.StatusInternalServerError)
        return
    }
    json.NewEncoder(w).Encode(user)
}
```

## Repository Respecting Context

```go
func (r *UserRepo) GetUser(ctx context.Context, id int) (*User, error) {
    row := r.db.QueryRowContext(ctx,  // Passes context to DB driver
        "SELECT id, name, email FROM users WHERE id = $1", id)

    var u User
    if err := row.Scan(&u.ID, &u.Name, &u.Email); err != nil {
        return nil, fmt.Errorf("get user %d: %w", id, err)
    }
    return &u, nil
}
// If ctx is cancelled, QueryRowContext returns immediately with ctx.Err()
```

## Fan-Out with Cancellation

```go
func fetchFromServices(ctx context.Context) (*AggregatedResult, error) {
    ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
    defer cancel()

    resultCh := make(chan *ServiceResult, 3)
    errCh := make(chan error, 3)

    for _, svc := range []string{"users", "orders", "inventory"} {
        go func(svcName string) {
            result, err := callService(ctx, svcName)  // Respects cancellation
            if err != nil { errCh <- err; return }
            resultCh <- result
        }(svc)
    }

    var results []*ServiceResult
    for i := 0; i < 3; i++ {
        select {
        case r := <-resultCh:
            results = append(results, r)
        case err := <-errCh:
            cancel()  // Cancel remaining requests on first error
            return nil, err
        case <-ctx.Done():
            return nil, ctx.Err()
        }
    }
    return aggregate(results), nil
}
```

## Context Values (Use Sparingly)

```go
type contextKey string
const requestIDKey contextKey = "request_id"

// Set
ctx = context.WithValue(ctx, requestIDKey, uuid.New().String())

// Get
requestID, ok := ctx.Value(requestIDKey).(string)
// Use only for request-scoped data like trace IDs, auth tokens
// NEVER for passing function arguments — that's what parameters are for
```
